public static Schema convertToSchema(
            DataType dataType, String rowName, Map<String, String> rowNameMapping) {
        if (rowNameMapping.containsKey(rowName)) {
            rowName = rowNameMapping.get(rowName);
        }

        int precision;
        boolean nullable = dataType.isNullable();
        switch (dataType.getTypeRoot()) {
            case BOOLEAN:
                Schema bool = SchemaBuilder.builder().booleanType();
                return nullable ? nullableSchema(bool) : bool;
            case TINYINT:
            case SMALLINT:
            case INTEGER:
                Schema integer = SchemaBuilder.builder().intType();
                return nullable ? nullableSchema(integer) : integer;
            case BIGINT:
                Schema bigint = SchemaBuilder.builder().longType();
                return nullable ? nullableSchema(bigint) : bigint;
            case FLOAT:
                Schema f = SchemaBuilder.builder().floatType();
                return nullable ? nullableSchema(f) : f;
            case DOUBLE:
                Schema d = SchemaBuilder.builder().doubleType();
                return nullable ? nullableSchema(d) : d;
            case CHAR:
            case VARCHAR:
                Schema str = SchemaBuilder.builder().stringType();
                return nullable ? nullableSchema(str) : str;
            case BINARY:
            case VARBINARY:
            case BLOB:
                Schema binary = SchemaBuilder.builder().bytesType();
                return nullable ? nullableSchema(binary) : binary;
            case TIMESTAMP_WITHOUT_TIME_ZONE:
                // use long to represents Timestamp
                final TimestampType timestampType = (TimestampType) dataType;
                precision = timestampType.getPrecision();
                org.apache.avro.LogicalType avroLogicalType;
                if (precision <= 3) {
                    avroLogicalType = LogicalTypes.timestampMillis();
                } else if (precision <= 6) {
                    avroLogicalType = LogicalTypes.timestampMicros();
                } else {
                    throw new IllegalArgumentException(
                            "Avro does not support TIMESTAMP type "
                                    + "with precision: "
                                    + precision
                                    + ", it only supports precision less than 6.");
                }
                Schema timestamp = avroLogicalType.addToSchema(SchemaBuilder.builder().longType());
                return nullable ? nullableSchema(timestamp) : timestamp;
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                final LocalZonedTimestampType localTimestampType =
                        (LocalZonedTimestampType) dataType;
                precision = localTimestampType.getPrecision();
                org.apache.avro.LogicalType localTimestampLogicalType;
                if (precision <= 3) {
                    localTimestampLogicalType = LogicalTypes.localTimestampMillis();
                } else if (precision <= 6) {
                    localTimestampLogicalType = LogicalTypes.localTimestampMicros();
                } else {
                    throw new IllegalArgumentException(
                            "Avro does not support TIMESTAMP type "
                                    + "with precision: "
                                    + precision
                                    + ", it only supports precision less than 6.");
                }
                Schema localTimestampSchema =
                        localTimestampLogicalType.addToSchema(SchemaBuilder.builder().longType());
                return nullable ? nullableSchema(localTimestampSchema) : localTimestampSchema;
            case DATE:
                // use int to represents Date
                Schema date = LogicalTypes.date().addToSchema(SchemaBuilder.builder().intType());
                return nullable ? nullableSchema(date) : date;
            case TIME_WITHOUT_TIME_ZONE:
                precision = ((TimeType) dataType).getPrecision();
                if (precision > 3) {
                    throw new IllegalArgumentException(
                            "Avro does not support TIME type with precision: "
                                    + precision
                                    + ", it only supports precision less than 3.");
                }
                // use int to represents Time, we only support millisecond when deserialization
                Schema time =
                        LogicalTypes.timeMillis().addToSchema(SchemaBuilder.builder().intType());
                return nullable ? nullableSchema(time) : time;
            case DECIMAL:
                DecimalType decimalType = (DecimalType) dataType;
                // store BigDecimal as byte[]
                Schema decimal =
                        LogicalTypes.decimal(decimalType.getPrecision(), decimalType.getScale())
                                .addToSchema(SchemaBuilder.builder().bytesType());
                return nullable ? nullableSchema(decimal) : decimal;
            case ROW:
                RowType rowType = (RowType) dataType;
                // we have to make sure the record name is different in a Schema
                SchemaBuilder.FieldAssembler<Schema> builder =
                        SchemaBuilder.builder().record(rowName).fields();
                for (DataField dataField : rowType.getFields()) {
                    String fieldName = dataField.name();
                    DataType fieldType = dataField.type();

                    FieldBuilder<Schema> name = builder.name(fieldName);

                    // Add required Field IDs to support ID-based column pruning.
                    // https://iceberg.apache.org/spec/#avro
                    if (rowNameMapping.containsKey(ICEBERG)) {
                        name.prop("field-id", dataField.id());
                    }

                    SchemaBuilder.GenericDefault<Schema> fieldBuilder =
                            name.type(
                                    convertToSchema(
                                            fieldType, rowName + "_" + fieldName, rowNameMapping));

                    if (fieldType.isNullable()) {
                        builder = fieldBuilder.withDefault(null);
                    } else {
                        builder = fieldBuilder.noDefault();
                    }
                }
                Schema record = builder.endRecord();
                return nullable ? nullableSchema(record) : record;
            case MULTISET:
            case MAP:
                DataType keyType = extractKeyTypeToAvroMap(dataType);
                DataType valueType = extractValueTypeToAvroMap(dataType);
                Schema map;
                if (isArrayMap(dataType)) {
                    // Avro only natively support map with string key.
                    // To represent a map with non-string key, we use an array containing several
                    // rows. The first field of a row is the key, and the second field is the value.

                    // Add required Field IDs to support ID-based column pruning.
                    // https://iceberg.apache.org/spec/#avro
                    if (rowNameMapping.containsKey(ICEBERG)) {
                        rowName =
                                Optional.ofNullable(rowNameMapping.get("kv_name_" + rowName))
                                        .orElse(rowName);
                    }

                    FieldBuilder<Schema> key =
                            SchemaBuilder.builder().record(rowName).fields().name("key");

                    // Add required Field IDs to support ID-based column pruning.
                    // https://iceberg.apache.org/spec/#avro
                    if (rowNameMapping.containsKey(ICEBERG)) {
                        Optional.ofNullable(rowNameMapping.get("k_id_" + rowName))
                                .map(Integer::valueOf)
                                .ifPresent(fieldId -> key.prop("field-id", fieldId));
                    }

                    FieldBuilder<Schema> value =
                            key.type(convertToSchema(keyType, rowName + "_key", rowNameMapping))
                                    .noDefault()
                                    .name("value");

                    // Add required Field IDs to support ID-based column pruning.
                    // https://iceberg.apache.org/spec/#avro
                    if (rowNameMapping.containsKey(ICEBERG)) {
                        Optional.ofNullable(rowNameMapping.get("v_id_" + rowName))
                                .map(Integer::valueOf)
                                .ifPresent(fieldId -> value.prop("field-id", fieldId));
                    }

                    SchemaBuilder.GenericDefault<Schema> kvBuilder =
                            value.type(
                                    convertToSchema(valueType, rowName + "_value", rowNameMapping));

                    SchemaBuilder.FieldAssembler<Schema> assembler =
                            valueType.isNullable()
                                    ? kvBuilder.withDefault(null)
                                    : kvBuilder.noDefault();
                    map = SchemaBuilder.builder().array().items(assembler.endRecord());
                    // Compatible with Iceberg's avro format.
                    // We don't use avro's logical type to check if an array field is actually a
                    // map. We use Paimon's DataType to check this.
                    map = LogicalMap.get().addToSchema(map);
                } else {
                    map =
                            SchemaBuilder.builder()
                                    .map()
                                    .values(convertToSchema(valueType, rowName, rowNameMapping));
                }
                return nullable ? nullableSchema(map) : map;
            case ARRAY:
            case VECTOR:
                DataType elementType =
                        dataType.getTypeRoot() == DataTypeRoot.ARRAY
                                ? ((ArrayType) dataType).getElementType()
                                : ((VectorType) dataType).getElementType();

                ArrayBuilder<Schema> arrayBuilder = SchemaBuilder.builder().array();

                // Add required Field IDs to support ID-based column pruning.
                // https://iceberg.apache.org/spec/#avro
                if (rowNameMapping.containsKey(ICEBERG)) {
                    Optional.ofNullable(rowNameMapping.get("array_id_" + rowName))
                            .map(Integer::valueOf)
                            .ifPresent(elementId -> arrayBuilder.prop("element-id", elementId));
                }

                Schema array =
                        arrayBuilder.items(convertToSchema(elementType, rowName, rowNameMapping));
                return nullable ? nullableSchema(array) : array;
            default:
                throw new UnsupportedOperationException(
                        "Unsupported to derive Schema for type: " + dataType);
        }
    }

public static Object castFromStringInternal(String s, DataType type, boolean isCdcValue) {
        BinaryString str = BinaryString.fromString(s);
        switch (type.getTypeRoot()) {
            case CHAR:
            case VARCHAR:
                int stringLength = DataTypeChecks.getLength(type);
                if (stringLength != VarCharType.MAX_LENGTH && str.numChars() > stringLength) {
                    throw new IllegalArgumentException(
                            String.format(
                                    "Length of type %s is %d, but casting result has a length of %d",
                                    type, stringLength, s.length()));
                }
                return str;
            case BOOLEAN:
                return BinaryStringUtils.toBoolean(str);
            case BINARY:
                return isCdcValue
                        ? Base64.getDecoder().decode(s)
                        : s.getBytes(StandardCharsets.UTF_8);
            case VARBINARY:
                int binaryLength = DataTypeChecks.getLength(type);
                byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
                if (bytes.length > binaryLength) {
                    throw new IllegalArgumentException(
                            String.format(
                                    "Length of type %s is %d, but casting result has a length of %d",
                                    type, binaryLength, bytes.length));
                }
                return bytes;
            case DECIMAL:
                DecimalType decimalType = (DecimalType) type;
                return Decimal.fromBigDecimal(
                        new BigDecimal(s), decimalType.getPrecision(), decimalType.getScale());
            case TINYINT:
                return Byte.valueOf(s);
            case SMALLINT:
                return Short.valueOf(s);
            case INTEGER:
                return Integer.valueOf(s);
            case BIGINT:
                return Long.valueOf(s);
            case FLOAT:
                double d = Double.parseDouble(s);
                if (d == ((float) d)) {
                    return (float) d;
                } else {
                    // Compatible canal-cdc
                    Float f = Float.valueOf(s);
                    if (!f.toString().equals(Double.toString(d))) {
                        throw new NumberFormatException(
                                s + " cannot be cast to float due to precision loss");
                    } else {
                        return f;
                    }
                }
            case DOUBLE:
                return Double.valueOf(s);
            case DATE:
                return BinaryStringUtils.toDate(str);
            case TIME_WITHOUT_TIME_ZONE:
                return BinaryStringUtils.toTime(str);
            case TIMESTAMP_WITHOUT_TIME_ZONE:
                TimestampType timestampType = (TimestampType) type;
                return BinaryStringUtils.toTimestamp(str, timestampType.getPrecision());
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                LocalZonedTimestampType localZonedTimestampType = (LocalZonedTimestampType) type;
                return BinaryStringUtils.toTimestamp(
                        str, localZonedTimestampType.getPrecision(), TimeZone.getDefault());
            case ARRAY:
                ArrayType arrayType = (ArrayType) type;
                DataType elementType = arrayType.getElementType();
                try {
                    JsonNode arrayNode = OBJECT_MAPPER.readTree(s);
                    if (!arrayNode.isArray()) {
                        throw new IllegalArgumentException(
                                String.format(
                                        "Expected a JSON array for type %s, but got %s",
                                        type, arrayNode.getNodeType()));
                    }
                    List<Object> resultList = new ArrayList<>();
                    for (JsonNode elementNode : arrayNode) {
                        if (!elementNode.isNull()) {
                            String elementJson;
                            if (elementNode.isTextual()) {
                                elementJson = elementNode.asText();
                            } else {
                                elementJson = elementNode.toString();
                            }
                            Object elementObject =
                                    castFromStringInternal(elementJson, elementType, isCdcValue);
                            resultList.add(elementObject);
                        } else {
                            resultList.add(null);
                        }
                    }
                    return new GenericArray(resultList.toArray());
                } catch (JsonProcessingException e) {
                    LOG.info(
                            String.format(
                                    "Failed to parse ARRAY for type %s with value %s", type, s),
                            e);
                    // try existing code flow
                    if (elementType instanceof VarCharType) {
                        if (s.startsWith("[")) {
                            s = s.substring(1);
                        }
                        if (s.endsWith("]")) {
                            s = s.substring(0, s.length() - 1);
                        }
                        String[] ss = s.split(",");
                        BinaryString[] binaryStrings = new BinaryString[ss.length];
                        for (int i = 0; i < ss.length; i++) {
                            binaryStrings[i] = BinaryString.fromString(ss[i]);
                        }
                        return new GenericArray(binaryStrings);
                    } else {
                        throw new UnsupportedOperationException("Unsupported type " + type);
                    }
                } catch (Exception e) {
                    throw new RuntimeException(
                            String.format("Failed to parse Json String %s", s), e);
                }
            case VECTOR:
                // Step 1: parse the string to an array
                VectorType vectorType = (VectorType) type;
                DataType vectorElementType = vectorType.getElementType();
                Object vectorArrayObject =
                        castFromStringInternal(s, DataTypes.ARRAY(vectorElementType), isCdcValue);
                if (!(vectorArrayObject instanceof InternalArray)) {
                    throw new RuntimeException(
                            "Unexpected parsed type during building a vector: "
                                    + vectorArrayObject.getClass());
                }
                // Step 2: build a vector
                return BinaryVector.fromInternalArray(
                        (InternalArray) vectorArrayObject, vectorElementType);
            case MAP:
                MapType mapType = (MapType) type;
                DataType keyType = mapType.getKeyType();
                DataType valueType = mapType.getValueType();
                try {
                    JsonNode mapNode = OBJECT_MAPPER.readTree(s);
                    if (!mapNode.isObject()) {
                        throw new IllegalArgumentException(
                                String.format(
                                        "Expected a JSON object for type %s, but got %s",
                                        type, mapNode.getNodeType()));
                    }
                    Map<Object, Object> resultMap = new HashMap<>();
                    mapNode.fields()
                            .forEachRemaining(
                                    entry -> {
                                        Object key =
                                                castFromStringInternal(
                                                        entry.getKey(), keyType, isCdcValue);
                                        Object value = null;
                                        if (!entry.getValue().isNull()) {
                                            if (entry.getValue().isTextual()) {
                                                value =
                                                        castFromStringInternal(
                                                                entry.getValue().asText(),
                                                                valueType,
                                                                isCdcValue);
                                            } else {
                                                value =
                                                        castFromStringInternal(
                                                                entry.getValue().toString(),
                                                                valueType,
                                                                isCdcValue);
                                            }
                                        }
                                        resultMap.put(key, value);
                                    });
                    return new GenericMap(resultMap);
                } catch (Exception e) {
                    throw new RuntimeException(
                            String.format("Failed to parse Json String %s", s), e);
                }
            case ROW:
                RowType rowType = (RowType) type;
                try {
                    JsonNode rowNode = OBJECT_MAPPER.readTree(s);
                    if (!rowNode.isObject()) {
                        throw new IllegalArgumentException(
                                String.format(
                                        "Expected a JSON object for type %s, but got %s",
                                        type, rowNode.getNodeType()));
                    }
                    GenericRow genericRow =
                            new GenericRow(
                                    rowType.getFields()
                                            .size()); // TODO: What about RowKind? always +I?
                    for (int pos = 0; pos < rowType.getFields().size(); ++pos) {
                        DataField field = rowType.getFields().get(pos);
                        JsonNode fieldNode = rowNode.get(field.name());
                        if (fieldNode != null && !fieldNode.isNull()) {
                            String fieldJson;
                            if (fieldNode.isTextual()) {
                                fieldJson = fieldNode.asText();
                            } else {
                                fieldJson = fieldNode.toString();
                            }
                            Object fieldObject =
                                    castFromStringInternal(fieldJson, field.type(), isCdcValue);
                            genericRow.setField(pos, fieldObject);
                        } else {
                            genericRow.setField(pos, null); // Handle null fields
                        }
                    }
                    return genericRow;
                } catch (Exception e) {
                    throw new RuntimeException(
                            String.format("Failed to parse Json String %s", s), e);
                }
            default:
                throw new UnsupportedOperationException("Unsupported type " + type);
        }
    }

public static Object cast(GenericVariant v, DataType dataType, VariantCastArgs castArgs) {
        if (dataType instanceof VariantType) {
            GenericVariantBuilder builder = new GenericVariantBuilder(false);
            builder.appendVariant(v);
            GenericVariant result = builder.result();
            return new GenericVariant(result.valueBuffer(), result.metadataBuffer());
        }

        Type variantType = v.getType();
        if (variantType == Type.NULL) {
            return null;
        }

        if (variantType == Type.UUID) {
            // There's no UUID type in Paimon. We only allow it to be cast to string.
            if (dataType.equals(DataTypes.STRING())) {
                return BinaryString.fromString(v.getUuid().toString());
            } else {
                return invalidCast(v, dataType, castArgs);
            }
        }

        if (dataType instanceof RowType) {
            RowType rowType = (RowType) dataType;
            if (variantType == Type.OBJECT) {
                GenericRow row = new GenericRow(rowType.getFieldCount());
                for (int i = 0; i < v.objectSize(); i++) {
                    GenericVariant.ObjectField field = v.getFieldAtIndex(i);
                    int idx = rowType.getFieldIndex(field.key);
                    if (idx != -1) {
                        row.setField(idx, cast(field.value, rowType.getTypeAt(idx), castArgs));
                    }
                }
                return row;
            } else {
                return invalidCast(v, dataType, castArgs);
            }
        } else if (dataType instanceof MapType) {
            MapType mapType = (MapType) dataType;
            DataType valueType = mapType.getValueType();
            if (mapType.getKeyType().equals(DataTypes.STRING())) {
                if (variantType == Type.OBJECT) {
                    int size = v.objectSize();
                    HashMap<BinaryString, Object> map = new HashMap<>();
                    for (int i = 0; i < size; i++) {
                        GenericVariant.ObjectField field = v.getFieldAtIndex(i);
                        map.put(
                                BinaryString.fromString(field.key),
                                cast(field.value, valueType, castArgs));
                    }
                    return new GenericMap(map);
                } else {
                    return invalidCast(v, dataType, castArgs);
                }
            } else {
                return invalidCast(v, dataType, castArgs);
            }
        } else if (dataType instanceof ArrayType) {
            ArrayType arrayType = (ArrayType) dataType;
            if (variantType == Type.ARRAY) {
                int size = v.arraySize();
                Object[] array = new Object[size];
                for (int i = 0; i < size; i++) {
                    array[i] = cast(v.getElementAtIndex(i), arrayType.getElementType(), castArgs);
                }
                return new GenericArray(array);
            } else {
                return invalidCast(v, dataType, castArgs);
            }
        } else {
            Object input;
            DataType inputType;
            switch (variantType) {
                case OBJECT:
                case ARRAY:
                    if (dataType.equals(DataTypes.STRING())) {
                        return BinaryString.fromString(v.toJson(castArgs.zoneId()));
                    } else {
                        return invalidCast(v, dataType, castArgs);
                    }
                case BOOLEAN:
                    input = v.getBoolean();
                    inputType = DataTypes.BOOLEAN();
                    break;
                case LONG:
                    input = v.getLong();
                    inputType = DataTypes.BIGINT();
                    break;
                case STRING:
                    input = BinaryString.fromString(v.getString());
                    inputType = DataTypes.STRING();
                    break;
                case DOUBLE:
                    input = v.getDouble();
                    inputType = DataTypes.DOUBLE();
                    break;
                case DECIMAL:
                    BigDecimal decimal = v.getDecimal();
                    if (decimal.scale() < 0) {
                        // stripTrailingZeros folds trailing zeros into a negative exponent,
                        // and a negative scale is not a Paimon decimal
                        decimal = decimal.setScale(0);
                    }
                    int scale = decimal.scale();
                    // precision() counts the digits of the unscaled value, so it is smaller than
                    // the scale for a value below 0.1, which DecimalType rejects. The variant
                    // writer caps both at MAX_DECIMAL16_PRECISION, so this stays in range.
                    int precision = Math.max(decimal.precision(), scale);
                    input = Decimal.fromBigDecimal(decimal, precision, scale);
                    inputType = DataTypes.DECIMAL(precision, scale);
                    break;
                case DATE:
                    input = (int) v.getLong();
                    inputType = DataTypes.DATE();
                    break;
                case TIMESTAMP:
                    input = Timestamp.fromMicros(v.getLong());
                    inputType = DataTypes.TIMESTAMP_WITH_LOCAL_TIME_ZONE();
                    break;
                case TIMESTAMP_NTZ:
                    input = Timestamp.fromMicros(v.getLong());
                    inputType = DataTypes.TIMESTAMP();
                    break;
                case FLOAT:
                    input = v.getFloat();
                    inputType = DataTypes.FLOAT();
                    break;
                case BINARY:
                    input = v.getBinary();
                    inputType = DataTypes.BYTES();
                    break;
                default:
                    // todo: support other types
                    throw new IllegalArgumentException("Unsupported type: " + v.getType());
            }

            if (inputType.equals(dataType)) {
                return input;
            }

            CastExecutor<Object, Object> resolve =
                    (CastExecutor<Object, Object>) CastExecutors.resolve(inputType, dataType);
            if (resolve != null) {
                try {
                    return resolve.cast(input);
                } catch (Exception e) {
                    return invalidCast(v, dataType, castArgs);
                }
            }

            return invalidCast(v, dataType, castArgs);
        }
    }

public static void rebuild(
            ShreddedRow row,
            ByteBuffer metadata,
            VariantSchema schema,
            GenericVariantBuilder builder) {
        int typedIdx = schema.typedIdx;
        int variantIdx = schema.variantIdx;
        if (typedIdx >= 0 && !row.isNullAt(typedIdx)) {
            if (schema.scalarSchema != null) {
                VariantSchema.ScalarType scalar = schema.scalarSchema;
                if (scalar instanceof VariantSchema.StringType) {
                    builder.appendString(row.getString(typedIdx));
                } else if (scalar instanceof VariantSchema.IntegralType) {
                    VariantSchema.IntegralType it = (VariantSchema.IntegralType) scalar;
                    long value = 0;
                    switch (it.size) {
                        case BYTE:
                            value = row.getByte(typedIdx);
                            break;
                        case SHORT:
                            value = row.getShort(typedIdx);
                            break;
                        case INT:
                            value = row.getInt(typedIdx);
                            break;
                        case LONG:
                            value = row.getLong(typedIdx);
                            break;
                    }
                    builder.appendLong(value);
                } else if (scalar instanceof VariantSchema.FloatType) {
                    builder.appendFloat(row.getFloat(typedIdx));
                } else if (scalar instanceof VariantSchema.DoubleType) {
                    builder.appendDouble(row.getDouble(typedIdx));
                } else if (scalar instanceof VariantSchema.BooleanType) {
                    builder.appendBoolean(row.getBoolean(typedIdx));
                } else if (scalar instanceof VariantSchema.BinaryType) {
                    builder.appendBinary(row.getBinaryBuffer(typedIdx));
                } else if (scalar instanceof VariantSchema.UuidType) {
                    builder.appendUuid(row.getUuid(typedIdx));
                } else if (scalar instanceof VariantSchema.DecimalType) {
                    VariantSchema.DecimalType dt = (VariantSchema.DecimalType) scalar;
                    builder.appendDecimal(row.getDecimal(typedIdx, dt.precision, dt.scale));
                } else if (scalar instanceof VariantSchema.DateType) {
                    builder.appendDate(row.getInt(typedIdx));
                } else if (scalar instanceof VariantSchema.TimestampType) {
                    builder.appendTimestamp(row.getTimestamp(typedIdx, 6).toMicros());
                } else {
                    assert scalar instanceof VariantSchema.TimestampNTZType;
                    builder.appendTimestampNtz(row.getTimestamp(typedIdx, 6).toMicros());
                }
            } else if (schema.arraySchema != null) {
                VariantSchema elementSchema = schema.arraySchema;
                ShreddedRow array = row.getArray(typedIdx);
                int start = builder.getWritePos();
                ArrayList<Integer> offsets = new ArrayList<>(array.numElements());
                for (int i = 0; i < array.numElements(); i++) {
                    offsets.add(builder.getWritePos() - start);
                    rebuild(
                            array.getStruct(i, elementSchema.numFields),
                            metadata,
                            elementSchema,
                            builder);
                }
                builder.finishWritingArray(start, offsets);
            } else {
                ShreddedRow object = row.getStruct(typedIdx, schema.objectSchema.length);
                ArrayList<GenericVariantBuilder.FieldEntry> fields = new ArrayList<>();
                int start = builder.getWritePos();
                for (int fieldIdx = 0; fieldIdx < schema.objectSchema.length; ++fieldIdx) {
                    // Shredded field must not be null.
                    if (object.isNullAt(fieldIdx)) {
                        throw malformedVariant();
                    }
                    String fieldName = schema.objectSchema[fieldIdx].fieldName;
                    VariantSchema fieldSchema = schema.objectSchema[fieldIdx].schema;
                    ShreddedRow fieldValue = object.getStruct(fieldIdx, fieldSchema.numFields);
                    // If the field doesn't have non-null `typed_value` or `value`, it is missing.
                    if ((fieldSchema.typedIdx >= 0 && !fieldValue.isNullAt(fieldSchema.typedIdx))
                            || (fieldSchema.variantIdx >= 0
                                    && !fieldValue.isNullAt(fieldSchema.variantIdx))) {
                        int id = builder.addKey(fieldName);
                        fields.add(
                                new GenericVariantBuilder.FieldEntry(
                                        fieldName, id, builder.getWritePos() - start));
                        rebuild(fieldValue, metadata, fieldSchema, builder);
                    }
                }
                if (variantIdx >= 0 && !row.isNullAt(variantIdx)) {
                    // Add the leftover fields in the variant binary.
                    GenericVariant v =
                            new GenericVariant(row.getBinaryBuffer(variantIdx), metadata);
                    if (v.getType() != GenericVariantUtil.Type.OBJECT) {
                        throw malformedVariant();
                    }
                    for (int i = 0; i < v.objectSize(); ++i) {
                        GenericVariant.ObjectField field = v.getFieldAtIndex(i);
                        // `value` must not contain any shredded field.
                        if (schema.objectSchemaMap.containsKey(field.key)) {
                            throw malformedVariant();
                        }
                        int id = builder.addKey(field.key);
                        fields.add(
                                new GenericVariantBuilder.FieldEntry(
                                        field.key, id, builder.getWritePos() - start));
                        builder.appendVariant(field.value);
                    }
                }
                builder.finishWritingObject(start, fields);
            }
        } else if (variantIdx >= 0 && !row.isNullAt(variantIdx)) {
            // `typed_value` doesn't exist or is null. Read from `value`.
            builder.appendVariant(new GenericVariant(row.getBinaryBuffer(variantIdx), metadata));
        } else {
            // This means the variant is missing in a context where it must present, so the input
            // data is invalid.
            throw malformedVariant();
        }
    }

public static void validateTableSchema(TableSchema schema, Set<String> dynamicOptionKeys) {
        CoreOptions options = new CoreOptions(schema.options());

        validateOnlyContainPrimitiveType(schema.fields(), schema.primaryKeys(), "primary key");
        validateOnlyContainPrimitiveType(schema.fields(), schema.partitionKeys(), "partition");
        // reject here rather than only at create time, so ALTER cannot turn the option on for a
        // table type that ignores it
        validateQueryAuthTableType(options.type(), options.queryAuthEnabled());

        if (options.primaryKeyNullable() && schema.primaryKeys().isEmpty()) {
            throw new IllegalArgumentException(
                    String.format(
                            "Option '%s' can only be enabled for a table with primary keys.",
                            CoreOptions.PRIMARY_KEY_NULLABLE.key()));
        }

        validateBucket(schema, options);

        validateStartupMode(options);

        validateFieldsPrefix(schema, options);

        validateSequenceField(schema, options);

        validateSequenceGroupOrderingFields(schema, options);

        validateMergeFunction(schema);

        ChangelogProducer changelogProducer = options.changelogProducer();
        if (schema.primaryKeys().isEmpty() && changelogProducer != ChangelogProducer.NONE) {
            throw new UnsupportedOperationException(
                    String.format(
                            "Can not set %s on table without primary keys, please define primary keys.",
                            CHANGELOG_PRODUCER.key()));
        }
        if (options.streamingReadOverwrite()
                && (changelogProducer == ChangelogProducer.FULL_COMPACTION
                        || changelogProducer == ChangelogProducer.LOOKUP)) {
            throw new UnsupportedOperationException(
                    String.format(
                            "Cannot set %s to true when changelog producer is %s or %s because it will read duplicated changes.",
                            STREAMING_READ_OVERWRITE.key(),
                            ChangelogProducer.FULL_COMPACTION,
                            ChangelogProducer.LOOKUP));
        }

        if (options.fullCompactionDeltaCommits() != null
                && changelogProducer == ChangelogProducer.LOOKUP) {
            throw new UnsupportedOperationException(
                    String.format(
                            "'%s' is incompatible with '%s'='%s'. "
                                    + "Use '%s'='%s' to get periodic full compaction with changelog generation, "
                                    + "or remove '%s'.",
                            FULL_COMPACTION_DELTA_COMMITS.key(),
                            CHANGELOG_PRODUCER.key(),
                            ChangelogProducer.LOOKUP,
                            CHANGELOG_PRODUCER.key(),
                            ChangelogProducer.FULL_COMPACTION,
                            FULL_COMPACTION_DELTA_COMMITS.key()));
        }

        checkArgument(
                options.targetFileRowNum() > 0,
                CoreOptions.TARGET_FILE_ROW_NUM.key() + " should be at least 1");

        checkArgument(
                options.snapshotNumRetainMin() > 0,
                SNAPSHOT_NUM_RETAINED_MIN.key() + " should be at least 1");
        checkArgument(
                options.snapshotNumRetainMin() <= options.snapshotNumRetainMax(),
                SNAPSHOT_NUM_RETAINED_MIN.key()
                        + " should not be larger than "
                        + SNAPSHOT_NUM_RETAINED_MAX.key());

        checkArgument(
                options.changelogNumRetainMin() > 0,
                CHANGELOG_NUM_RETAINED_MIN.key() + " should be at least 1");
        checkArgument(
                options.changelogNumRetainMin() <= options.changelogNumRetainMax(),
                CHANGELOG_NUM_RETAINED_MIN.key()
                        + " should not be larger than "
                        + CHANGELOG_NUM_RETAINED_MAX.key());

        FileFormat fileFormat =
                FileFormat.fromIdentifier(options.formatType(), new Options(schema.options()));
        RowType tableRowType = new RowType(schema.fields());
        validateGeospatialTypes(schema, options, tableRowType);
        validateIcebergTimestampPrecisions(tableRowType, options);
        validateIcebergTimePrecisions(tableRowType, options);
        validateBlobFields(tableRowType, options);
        Set<String> blobDescriptorFields = validateBlobDescriptorFields(tableRowType, options);
        Set<String> blobViewFields =
                validateBlobViewFields(tableRowType, options, blobDescriptorFields);
        validateVideoFrameFields(
                schema, tableRowType, options, blobDescriptorFields, blobViewFields);
        validatePrimaryKeyBlobKeyConfiguration(schema, options);
        validatePrimaryKeyBlobConfiguration(schema, options);
        Set<String> blobInlineFields = new HashSet<>(blobDescriptorFields);
        blobInlineFields.addAll(blobViewFields);

        List<DataField> fieldsInNormalFile = new ArrayList<>();
        Set<String> fieldsInDedicatedFile =
                SetUtils.union(
                        fieldNamesInBlobFile(tableRowType, blobInlineFields),
                        fieldNamesInVectorFile(tableRowType, options.withVectorFormat()));
        for (DataField field : tableRowType.getFields()) {
            if (!fieldsInDedicatedFile.contains(field.name())) {
                fieldsInNormalFile.add(field);
            }
        }
        fileFormat.validateDataFields(new RowType(fieldsInNormalFile));

        for (Map.Entry<Integer, String> entry : options.fileFormatPerLevel().entrySet()) {
            if (!"avro".equalsIgnoreCase(entry.getValue())) {
                continue;
            }
            for (DataField field : fieldsInNormalFile) {
                DataType type = field.type();
                int precision = -1;
                if (type instanceof TimestampType) {
                    precision = ((TimestampType) type).getPrecision();
                } else if (type instanceof LocalZonedTimestampType) {
                    precision = ((LocalZonedTimestampType) type).getPrecision();
                }
                if (precision > 6) {
                    throw new IllegalArgumentException(
                            String.format(
                                    "'%s' entry '%d:avro' is incompatible with column '%s' of type %s: "
                                            + "Avro supports timestamp precision up to 6, got %d. "
                                            + "Either lower the column precision, drop the per-level mapping for level %d, "
                                            + "or use a different format (parquet or orc) for that level.",
                                    CoreOptions.FILE_FORMAT_PER_LEVEL.key(),
                                    entry.getKey(),
                                    field.name(),
                                    type,
                                    precision,
                                    entry.getKey()));
                }
            }
        }

        // Check column names in schema
        schema.fieldNames()
                .forEach(
                        f -> {
                            checkState(
                                    !SYSTEM_FIELD_NAMES.contains(f),
                                    String.format(
                                            "Field name[%s] in schema cannot be exist in %s",
                                            f, SYSTEM_FIELD_NAMES));
                            checkState(
                                    !f.startsWith(KEY_FIELD_PREFIX),
                                    String.format(
                                            "Field name[%s] in schema cannot start with [%s]",
                                            f, KEY_FIELD_PREFIX));
                        });

        if (schema.primaryKeys().isEmpty() && options.streamingReadOverwrite()) {
            throw new RuntimeException(
                    String.format(
                            "Doesn't support streaming read the changes from overwrite when the primary keys are "
                                    + "not defined. Please use %s to enable the streaming read overwrite commit for append table.",
                            CoreOptions.STREAMING_READ_APPEND_OVERWRITE.key()));
        }

        String recordLevelTimeField = options.recordLevelTimeField();
        if (recordLevelTimeField != null) {
            Optional<DataField> field =
                    schema.fields().stream()
                            .filter(dataField -> dataField.name().equals(recordLevelTimeField))
                            .findFirst();
            if (!field.isPresent()) {
                throw new IllegalArgumentException(
                        String.format(
                                "Can not find time field %s for record level expire.",
                                recordLevelTimeField));
            }
            DataType dataType = field.get().type();
            if (!(dataType instanceof IntType
                    || dataType instanceof BigIntType
                    || dataType instanceof TimestampType
                    || dataType instanceof LocalZonedTimestampType)) {
                throw new IllegalArgumentException(
                        String.format(
                                "The record level time field type should be one of INT, BIGINT, or TIMESTAMP, but field type is %s.",
                                dataType));
            }
        }

        if (options.mergeEngine() == MergeEngine.FIRST_ROW) {
            if (options.changelogProducer() != ChangelogProducer.LOOKUP
                    && options.changelogProducer() != ChangelogProducer.NONE) {
                throw new IllegalArgumentException(
                        "Only support 'none' and 'lookup' changelog-producer on FIRST_ROW merge engine");
            }
        }

        options.rowkindField()
                .ifPresent(
                        field ->
                                checkArgument(
                                        schema.fieldNames().contains(field),
                                        "Rowkind field: '%s' can not be found in table schema.",
                                        field));

        if (options.deletionVectorsEnabled()) {
            validateForDeletionVectors(options);
        }

        if (options.snapshotSequenceOrdering()) {
            validateSnapshotSequenceOrdering(schema, options, dynamicOptionKeys);
        }

        // vector field names must point to vector type
        Set<String> fieldNamesSpecifiedAsVector = options.vectorField();
        schema.fields()
                .forEach(
                        f ->
                                checkState(
                                        !fieldNamesSpecifiedAsVector.contains(f.name())
                                                || VECTOR.equals(f.type().getTypeRoot()),
                                        String.format(
                                                "Field name[%s] is configured as vector-field so"
                                                        + " the type must be vector, but it is %s",
                                                f.name(), f.type())));
        // vector field names must exist in table schema
        schema.fieldNames().forEach(fieldNamesSpecifiedAsVector::remove);
        checkArgument(
                fieldNamesSpecifiedAsVector.isEmpty(),
                "Some of the columns specified as vector-field are unknown.");

        validatePrimaryKeyIndexColumns(options);
        validatePrimaryKeySortedIndexes(schema, options);
        validatePrimaryKeyVectorIndex(schema, options);
        validatePrimaryKeyFullTextIndex(schema, options);

        validateMergeFunctionFactory(schema);

        validateMapStorageLayout(schema, options);
        validateVariantShreddingInferenceOptions(options);

        validateFileIndex(schema);

        validateRowTracking(schema, options);

        validateIncrementalClustering(schema, options);

        validateChainTable(schema, options);

        validateChangelogReadSequenceNumber(schema, options);

        validatePkClusteringOverride(options);

        validateManifestSort(schema, options);
    }

public static Type convertToParquetType(String name, DataType type, int fieldId, int depth) {
        Type.Repetition repetition =
                type.isNullable() ? Type.Repetition.OPTIONAL : Type.Repetition.REQUIRED;
        switch (type.getTypeRoot()) {
            case CHAR:
            case VARCHAR:
                return Types.primitive(PrimitiveType.PrimitiveTypeName.BINARY, repetition)
                        .as(LogicalTypeAnnotation.stringType())
                        .named(name)
                        .withId(fieldId);
            case BOOLEAN:
                return Types.primitive(PrimitiveType.PrimitiveTypeName.BOOLEAN, repetition)
                        .named(name)
                        .withId(fieldId);
            case BINARY:
            case VARBINARY:
            case BLOB:
                return Types.primitive(PrimitiveType.PrimitiveTypeName.BINARY, repetition)
                        .named(name)
                        .withId(fieldId);
            case GEOMETRY:
                return Types.primitive(PrimitiveType.PrimitiveTypeName.BINARY, repetition)
                        .as(LogicalTypeAnnotation.geometryType(((GeometryType) type).getCrs()))
                        .columnOrder(ColumnOrder.undefined())
                        .named(name)
                        .withId(fieldId);
            case GEOGRAPHY:
                GeographyType geographyType = (GeographyType) type;
                return Types.primitive(PrimitiveType.PrimitiveTypeName.BINARY, repetition)
                        .as(
                                LogicalTypeAnnotation.geographyType(
                                        geographyType.getCrs(),
                                        EdgeInterpolationAlgorithm.valueOf(
                                                geographyType.getAlgorithm().name())))
                        .columnOrder(ColumnOrder.undefined())
                        .named(name)
                        .withId(fieldId);
            case DECIMAL:
                int precision = ((DecimalType) type).getPrecision();
                int scale = ((DecimalType) type).getScale();
                if (is32BitDecimal(precision)) {
                    return Types.primitive(INT32, repetition)
                            .as(LogicalTypeAnnotation.decimalType(scale, precision))
                            .named(name)
                            .withId(fieldId);
                } else if (is64BitDecimal(precision)) {
                    return Types.primitive(INT64, repetition)
                            .as(LogicalTypeAnnotation.decimalType(scale, precision))
                            .named(name)
                            .withId(fieldId);
                } else {
                    return Types.primitive(FIXED_LEN_BYTE_ARRAY, repetition)
                            .as(LogicalTypeAnnotation.decimalType(scale, precision))
                            .length(computeMinBytesForDecimalPrecision(precision))
                            .named(name)
                            .withId(fieldId);
                }
            case TINYINT:
                return Types.primitive(INT32, repetition)
                        .as(LogicalTypeAnnotation.intType(8, true))
                        .named(name)
                        .withId(fieldId);
            case SMALLINT:
                return Types.primitive(INT32, repetition)
                        .as(LogicalTypeAnnotation.intType(16, true))
                        .named(name)
                        .withId(fieldId);
            case INTEGER:
                return Types.primitive(INT32, repetition).named(name).withId(fieldId);
            case BIGINT:
                return Types.primitive(INT64, repetition).named(name).withId(fieldId);
            case FLOAT:
                return Types.primitive(PrimitiveType.PrimitiveTypeName.FLOAT, repetition)
                        .named(name)
                        .withId(fieldId);
            case DOUBLE:
                return Types.primitive(PrimitiveType.PrimitiveTypeName.DOUBLE, repetition)
                        .named(name)
                        .withId(fieldId);
            case DATE:
                return Types.primitive(INT32, repetition)
                        .as(LogicalTypeAnnotation.dateType())
                        .named(name)
                        .withId(fieldId);
            case TIME_WITHOUT_TIME_ZONE:
                return Types.primitive(INT32, repetition)
                        .as(
                                LogicalTypeAnnotation.timeType(
                                        true, LogicalTypeAnnotation.TimeUnit.MILLIS))
                        .named(name)
                        .withId(fieldId);
            case TIMESTAMP_WITHOUT_TIME_ZONE:
                TimestampType timestampType = (TimestampType) type;
                return createTimestampWithLogicalType(
                                name, timestampType.getPrecision(), repetition, false)
                        .withId(fieldId);
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                LocalZonedTimestampType localZonedTimestampType = (LocalZonedTimestampType) type;
                return createTimestampWithLogicalType(
                                name, localZonedTimestampType.getPrecision(), repetition, true)
                        .withId(fieldId);
            case ARRAY:
            case VECTOR:
                DataType listElementType =
                        type instanceof ArrayType
                                ? ((ArrayType) type).getElementType()
                                : ((VectorType) type).getElementType();
                Type elementParquetType =
                        convertToParquetType(LIST_ELEMENT_NAME, listElementType, fieldId, depth + 1)
                                .withId(SpecialFields.getArrayElementFieldId(fieldId, depth + 1));
                return ConversionPatterns.listOfElements(repetition, name, elementParquetType)
                        .withId(fieldId);
            case MAP:
                MapType mapType = (MapType) type;
                DataType keyType = mapType.getKeyType();
                if (keyType.isNullable()) {
                    // key is nullable, but Parquet does not support nullable keys, so we configure
                    // it as not nullable
                    keyType = keyType.copy(false);
                }
                Type mapKeyParquetType =
                        convertToParquetType(MAP_KEY_NAME, keyType, fieldId, depth + 1)
                                .withId(SpecialFields.getMapKeyFieldId(fieldId, depth + 1));
                Type mapValueParquetType =
                        convertToParquetType(
                                        MAP_VALUE_NAME, mapType.getValueType(), fieldId, depth + 1)
                                .withId(SpecialFields.getMapValueFieldId(fieldId, depth + 1));
                return ConversionPatterns.mapType(
                                repetition,
                                name,
                                MAP_REPEATED_NAME,
                                mapKeyParquetType,
                                mapValueParquetType)
                        .withId(fieldId);
            case MULTISET:
                MultisetType multisetType = (MultisetType) type;
                DataType elementType = multisetType.getElementType();
                if (elementType.isNullable()) {
                    // element type is nullable, but Parquet does not support nullable map keys,
                    // so we configure it as not nullable
                    elementType = elementType.copy(false);
                }
                Type multisetKeyParquetType =
                        convertToParquetType(MAP_KEY_NAME, elementType, fieldId, depth + 1)
                                .withId(SpecialFields.getMapKeyFieldId(fieldId, depth + 1));
                Type multisetValueParquetType =
                        convertToParquetType(MAP_VALUE_NAME, new IntType(false), fieldId, depth + 1)
                                .withId(SpecialFields.getMapValueFieldId(fieldId, depth + 1));
                return ConversionPatterns.mapType(
                                repetition,
                                name,
                                MAP_REPEATED_NAME,
                                multisetKeyParquetType,
                                multisetValueParquetType)
                        .withId(fieldId);
            case ROW:
                RowType rowType = (RowType) type;
                Types.GroupBuilder<GroupType> groupTypeBuilder = Types.buildGroup(repetition);
                // TODO Use Variant until all engines are upgraded to the latest Parquet
                // if (VariantMetadataUtils.isVariantRowType(rowType)) {
                //     groupTypeBuilder.as(
                //            LogicalTypeAnnotation.variantType(Variant.VARIANT_SPEC_VERSION));
                // }
                return groupTypeBuilder
                        .addFields(convertToParquetTypes(rowType))
                        .named(name)
                        .withId(fieldId);
            case VARIANT:
                return Types.buildGroup(repetition)
                        // TODO Use Variant until all engines are upgraded to the latest Parquet
                        // .as(LogicalTypeAnnotation.variantType(Variant.VARIANT_SPEC_VERSION))
                        .addField(
                                Types.primitive(
                                                PrimitiveType.PrimitiveTypeName.BINARY,
                                                Type.Repetition.REQUIRED)
                                        .named(Variant.VALUE)
                                        .withId(0))
                        .addField(
                                Types.primitive(
                                                PrimitiveType.PrimitiveTypeName.BINARY,
                                                Type.Repetition.REQUIRED)
                                        .named(Variant.METADATA)
                                        .withId(1))
                        .named(name)
                        .withId(fieldId);
            default:
                throw new UnsupportedOperationException("Unsupported type: " + type);
        }
    }

public static DataField convertToPaimonField(Type parquetType) {
        LogicalTypeAnnotation logicalType = parquetType.getLogicalTypeAnnotation();
        DataType paimonDataType;

        if (parquetType.isPrimitive()) {
            switch (parquetType.asPrimitiveType().getPrimitiveTypeName()) {
                case BINARY:
                    if (logicalType instanceof LogicalTypeAnnotation.StringLogicalTypeAnnotation) {
                        paimonDataType = DataTypes.STRING();
                    } else if (logicalType
                            instanceof LogicalTypeAnnotation.GeometryLogicalTypeAnnotation) {
                        paimonDataType =
                                DataTypes.GEOMETRY(
                                        ((LogicalTypeAnnotation.GeometryLogicalTypeAnnotation)
                                                        logicalType)
                                                .getCrs());
                    } else if (logicalType
                            instanceof LogicalTypeAnnotation.GeographyLogicalTypeAnnotation) {
                        LogicalTypeAnnotation.GeographyLogicalTypeAnnotation geography =
                                (LogicalTypeAnnotation.GeographyLogicalTypeAnnotation) logicalType;
                        EdgeAlgorithm algorithm =
                                geography.getAlgorithm() == null
                                        ? null
                                        : EdgeAlgorithm.valueOf(geography.getAlgorithm().name());
                        paimonDataType = DataTypes.GEOGRAPHY(geography.getCrs(), algorithm);
                    } else {
                        paimonDataType = DataTypes.BYTES();
                    }
                    break;
                case BOOLEAN:
                    paimonDataType = DataTypes.BOOLEAN();
                    break;
                case FLOAT:
                    paimonDataType = DataTypes.FLOAT();
                    break;
                case DOUBLE:
                    paimonDataType = DataTypes.DOUBLE();
                    break;
                case INT32:
                    if (logicalType instanceof LogicalTypeAnnotation.DecimalLogicalTypeAnnotation) {
                        LogicalTypeAnnotation.DecimalLogicalTypeAnnotation decimalType =
                                (LogicalTypeAnnotation.DecimalLogicalTypeAnnotation) logicalType;
                        paimonDataType =
                                new DecimalType(decimalType.getPrecision(), decimalType.getScale());
                    } else if (logicalType
                            instanceof LogicalTypeAnnotation.IntLogicalTypeAnnotation) {
                        LogicalTypeAnnotation.IntLogicalTypeAnnotation intType =
                                (LogicalTypeAnnotation.IntLogicalTypeAnnotation) logicalType;
                        int bitWidth = intType.getBitWidth();
                        if (bitWidth == 8) {
                            paimonDataType = DataTypes.TINYINT();
                        } else if (bitWidth == 16) {
                            paimonDataType = DataTypes.SMALLINT();
                        } else {
                            paimonDataType = DataTypes.INT();
                        }
                    } else if (logicalType
                            instanceof LogicalTypeAnnotation.DateLogicalTypeAnnotation) {
                        paimonDataType = DataTypes.DATE();
                    } else if (logicalType
                            instanceof LogicalTypeAnnotation.TimeLogicalTypeAnnotation) {
                        paimonDataType = DataTypes.TIME();
                    } else {
                        paimonDataType = DataTypes.INT();
                    }
                    break;
                case INT64:
                    if (logicalType instanceof LogicalTypeAnnotation.DecimalLogicalTypeAnnotation) {
                        LogicalTypeAnnotation.DecimalLogicalTypeAnnotation decimalType =
                                (LogicalTypeAnnotation.DecimalLogicalTypeAnnotation) logicalType;
                        paimonDataType =
                                new DecimalType(decimalType.getPrecision(), decimalType.getScale());
                    } else if (logicalType
                            instanceof LogicalTypeAnnotation.TimestampLogicalTypeAnnotation) {
                        LogicalTypeAnnotation.TimestampLogicalTypeAnnotation timestampType =
                                (LogicalTypeAnnotation.TimestampLogicalTypeAnnotation) logicalType;
                        int precision;
                        if (timestampType.getUnit().equals(LogicalTypeAnnotation.TimeUnit.MILLIS)) {
                            precision = 3;
                        } else if (timestampType
                                .getUnit()
                                .equals(LogicalTypeAnnotation.TimeUnit.MICROS)) {
                            precision = 6;
                        } else {
                            precision = 9;
                        }
                        paimonDataType =
                                timestampType.isAdjustedToUTC()
                                        ? new LocalZonedTimestampType(precision)
                                        : new TimestampType(precision);
                    } else {
                        paimonDataType = DataTypes.BIGINT();
                    }
                    break;
                case INT96:
                    paimonDataType = new TimestampType(9);
                    break;
                case FIXED_LEN_BYTE_ARRAY:
                    LogicalTypeAnnotation.DecimalLogicalTypeAnnotation decimalType =
                            (LogicalTypeAnnotation.DecimalLogicalTypeAnnotation) logicalType;
                    paimonDataType =
                            new DecimalType(decimalType.getPrecision(), decimalType.getScale());
                    break;
                default:
                    throw new UnsupportedOperationException("Unsupported type: " + parquetType);
            }
            if (parquetType.getRepetition().equals(Type.Repetition.REQUIRED)) {
                paimonDataType = paimonDataType.notNull();
            }
            return new DataField(
                    parquetType.getId().intValue(), parquetType.getName(), paimonDataType);
        } else {
            GroupType groupType = parquetType.asGroupType();
            if (logicalType instanceof LogicalTypeAnnotation.ListLogicalTypeAnnotation) {
                paimonDataType =
                        new ArrayType(
                                convertToPaimonField(parquetListElementType(groupType)).type());
            } else if (logicalType instanceof LogicalTypeAnnotation.MapLogicalTypeAnnotation) {
                Pair<Type, Type> keyValueType = parquetMapKeyValueType(groupType);
                paimonDataType =
                        new MapType(
                                // Since parquet does not support nullable key, when converting
                                // back to Paimon, set as nullable by default.
                                convertToPaimonField(keyValueType.getLeft()).type().nullable(),
                                convertToPaimonField(keyValueType.getRight()).type());
            } else {
                paimonDataType =
                        new RowType(
                                groupType.getFields().stream()
                                        .map(ParquetSchemaConverter::convertToPaimonField)
                                        .collect(Collectors.toList()));
            }
        }

        if (parquetType.getRepetition().equals(Type.Repetition.REQUIRED)) {
            paimonDataType = paimonDataType.notNull();
        }

        return new DataField(parquetType.getId().intValue(), parquetType.getName(), paimonDataType);
    }

public static DataType merge(
            DataType base0,
            DataType update0,
            AtomicInteger highestFieldId,
            boolean typeWidening,
            boolean allowExplicitCast,
            boolean caseSensitive) {
        // Compare ignoring nullability; the base's nullability flows to the result.
        DataType base = base0.copy(true);
        DataType update = update0.copy(true);

        if (base.equals(update)) {
            return base0;
        } else if (base instanceof RowType && update instanceof RowType) {
            List<DataField> baseFields = ((RowType) base).getFields();
            List<DataField> updateFields = ((RowType) update).getFields();
            Map<String, DataField> updateFieldMap = buildFieldMap(updateFields, caseSensitive);
            List<DataField> updatedFields = new ArrayList<>();
            for (DataField baseField : baseFields) {
                if (updateFieldMap.containsKey(baseField.name())) {
                    DataField updateField = updateFieldMap.get(baseField.name());
                    DataType updatedDataType =
                            merge(
                                    baseField.type(),
                                    updateField.type(),
                                    highestFieldId,
                                    typeWidening,
                                    allowExplicitCast,
                                    caseSensitive);
                    updatedFields.add(
                            new DataField(
                                    baseField.id(),
                                    baseField.name(),
                                    updatedDataType,
                                    baseField.description(),
                                    baseField.defaultValue()));
                } else {
                    updatedFields.add(baseField);
                }
            }

            Map<String, DataField> baseFieldMap = buildFieldMap(baseFields, caseSensitive);
            for (DataField field : updateFields) {
                if (!baseFieldMap.containsKey(field.name())) {
                    updatedFields.add(assignIdForNewField(field, highestFieldId).copy(true));
                }
            }

            return new RowType(base0.isNullable(), updatedFields);
        } else if (base instanceof MapType && update instanceof MapType) {
            return new MapType(
                    base0.isNullable(),
                    merge(
                            ((MapType) base).getKeyType(),
                            ((MapType) update).getKeyType(),
                            highestFieldId,
                            typeWidening,
                            allowExplicitCast,
                            caseSensitive),
                    merge(
                            ((MapType) base).getValueType(),
                            ((MapType) update).getValueType(),
                            highestFieldId,
                            typeWidening,
                            allowExplicitCast,
                            caseSensitive));
        } else if (base instanceof ArrayType && update instanceof ArrayType) {
            return new ArrayType(
                    base0.isNullable(),
                    merge(
                            ((ArrayType) base).getElementType(),
                            ((ArrayType) update).getElementType(),
                            highestFieldId,
                            typeWidening,
                            allowExplicitCast,
                            caseSensitive));
        } else if (base instanceof MultisetType && update instanceof MultisetType) {
            return new MultisetType(
                    base0.isNullable(),
                    merge(
                            ((MultisetType) base).getElementType(),
                            ((MultisetType) update).getElementType(),
                            highestFieldId,
                            typeWidening,
                            allowExplicitCast,
                            caseSensitive));
        } else if (!typeWidening) {
            // Default: keep the existing leaf type — only column additions evolve the schema.
            // Incoming values are cast to this type by the alignment layer.
            return base0;
        } else if (base instanceof DecimalType && update instanceof DecimalType) {
            if (((DecimalType) base).getScale() == ((DecimalType) update).getScale()) {
                return new DecimalType(
                        base0.isNullable(),
                        Math.max(
                                ((DecimalType) base).getPrecision(),
                                ((DecimalType) update).getPrecision()),
                        ((DecimalType) base).getScale());
            } else {
                throw new UnsupportedOperationException(
                        String.format(
                                "Failed to merge decimal types with different scale: %s and %s",
                                base, update));
            }
        } else if (supportsDataTypesCast(base, update, allowExplicitCast)) {
            if (DataTypes.getLength(base).isPresent() && DataTypes.getLength(update).isPresent()) {
                // this will check and merge types which has a `length` attribute, like BinaryType,
                // CharType, VarBinaryType, VarCharType.
                if (allowExplicitCast
                        || DataTypes.getLength(base).getAsInt()
                                <= DataTypes.getLength(update).getAsInt()) {
                    return update.copy(base0.isNullable());
                } else {
                    throw new UnsupportedOperationException(
                            String.format(
                                    "Failed to merge the target type that has a smaller length: %s and %s",
                                    base, update));
                }
            } else if (DataTypes.getPrecision(base).isPresent()
                    && DataTypes.getPrecision(update).isPresent()) {
                // this will check and merge types which has a `precision` attribute, like
                // LocalZonedTimestampType, TimeType, TimestampType.
                if (allowExplicitCast
                        || DataTypes.getPrecision(base).getAsInt()
                                <= DataTypes.getPrecision(update).getAsInt()) {
                    return update.copy(base0.isNullable());
                } else {
                    throw new UnsupportedOperationException(
                            String.format(
                                    "Failed to merge the target type that has a lower precision: %s and %s",
                                    base, update));
                }
            } else {
                return update.copy(base0.isNullable());
            }
        } else {
            throw new UnsupportedOperationException(
                    String.format("Failed to merge data types %s and %s", base, update));
        }
    }

static Plan plan(
            long snapshotId,
            List<DataSplit> dataSplits,
            List<PrimaryKeyIndexDefinition> definitions,
            List<IndexManifestEntry> indexEntries) {
        Map<Pair<BinaryRow, Integer>, List<IndexFileMeta>> payloadsByBucket = new LinkedHashMap<>();
        for (IndexManifestEntry entry : indexEntries) {
            IndexFileMeta payload = entry.indexFile();
            GlobalIndexMeta meta = payload.globalIndexMeta();
            if (entry.kind() != FileKind.ADD || meta == null || meta.sourceMeta() == null) {
                continue;
            }
            Pair<BinaryRow, Integer> bucket = Pair.of(entry.partition(), entry.bucket());
            payloadsByBucket.computeIfAbsent(bucket, ignored -> new ArrayList<>()).add(payload);
        }

        List<PrimaryKeyIndexDefinition> scalarDefinitions = new ArrayList<>();
        for (PrimaryKeyIndexDefinition definition : definitions) {
            if (definition.family().isScalar()) {
                scalarDefinitions.add(definition);
            }
        }

        Map<Pair<BinaryRow, Integer>, List<DataFileMeta>> dataFilesByBucket = new LinkedHashMap<>();
        for (DataSplit split : dataSplits) {
            checkArgument(
                    split.snapshotId() == snapshotId,
                    "Data split snapshot %s does not match sorted-index scan snapshot %s.",
                    split.snapshotId(),
                    snapshotId);
            checkArgument(
                    !split.isStreaming(), "Primary-key sorted-index scan requires batch splits.");
            List<DeletionFile> deletions = split.deletionFiles().orElse(null);
            checkArgument(
                    deletions == null || deletions.size() == split.dataFiles().size(),
                    "Deletion files must align with data files in a sorted-index split.");
            List<DataFileMeta> dataFiles =
                    dataFilesByBucket.computeIfAbsent(
                            Pair.of(split.partition(), split.bucket()),
                            ignored -> new ArrayList<>());
            dataFiles.addAll(split.dataFiles());
        }

        Map<Pair<BinaryRow, Integer>, Map<String, Map<Integer, PkSortedIndexGroup>>>
                groupsByBucket = new LinkedHashMap<>();
        for (Map.Entry<Pair<BinaryRow, Integer>, List<DataFileMeta>> bucketEntry :
                dataFilesByBucket.entrySet()) {
            Pair<BinaryRow, Integer> bucket = bucketEntry.getKey();
            List<IndexFileMeta> bucketPayloads =
                    payloadsByBucket.getOrDefault(bucket, Collections.emptyList());
            Map<Integer, Set<PrimaryKeyIndexSourceFile>> activeSourceFilesByLevel = new HashMap<>();
            for (DataFileMeta dataFile : bucketEntry.getValue()) {
                if (PrimaryKeyIndexSourcePolicy.shouldRead(dataFile)) {
                    activeSourceFilesByLevel
                            .computeIfAbsent(dataFile.level(), ignored -> new HashSet<>())
                            .add(
                                    new PrimaryKeyIndexSourceFile(
                                            dataFile.fileName(), dataFile.rowCount()));
                }
            }
            Map<String, Map<Integer, PkSortedIndexGroup>> groupsBySource = new LinkedHashMap<>();
            for (PrimaryKeyIndexDefinition definition : scalarDefinitions) {
                List<IndexFileMeta> definitionPayloads = new ArrayList<>();
                for (IndexFileMeta payload : bucketPayloads) {
                    GlobalIndexMeta meta = payload.globalIndexMeta();
                    if (meta != null
                            && definition.indexType().equals(payload.indexType())
                            && definition.fieldId() == meta.indexFieldId()) {
                        definitionPayloads.add(payload);
                    }
                }
                try {
                    PkSortedBucketIndexState state =
                            PkSortedBucketIndexState.fromActiveDataFiles(
                                    definition.fieldId(),
                                    definition.indexType(),
                                    bucketEntry.getValue(),
                                    definitionPayloads);
                    for (PkSortedIndexGroup group : state.groups()) {
                        Set<PrimaryKeyIndexSourceFile> activeGroupSources =
                                activeSourceFilesByLevel.getOrDefault(
                                        group.dataLevel(), Collections.emptySet());
                        for (PrimaryKeyIndexSourceFile sourceFile : group.sourceFiles()) {
                            if (!activeGroupSources.contains(sourceFile)) {
                                continue;
                            }
                            groupsBySource
                                    .computeIfAbsent(
                                            sourceFile.fileName(), ignored -> new LinkedHashMap<>())
                                    .put(definition.fieldId(), group);
                        }
                    }
                } catch (RuntimeException e) {
                    rethrowIfInterrupted(e);
                    LOG.warn(
                            "Failed to plan primary-key sorted index for partition {}, bucket {} "
                                    + "and field {}; falling back to a raw scan for this field.",
                            bucket.getKey(),
                            bucket.getValue(),
                            definition.fieldId(),
                            e);
                }
            }
            groupsByBucket.put(bucket, groupsBySource);
        }

        List<FilePlan> files = new ArrayList<>();
        for (DataSplit split : dataSplits) {
            Map<String, Map<Integer, PkSortedIndexGroup>> groupsBySource =
                    groupsByBucket.getOrDefault(
                            Pair.of(split.partition(), split.bucket()), Collections.emptyMap());
            for (int fileIndex = 0; fileIndex < split.dataFiles().size(); fileIndex++) {
                DataFileMeta dataFile = split.dataFiles().get(fileIndex);
                Map<Integer, PkSortedIndexGroup> groups =
                        groupsBySource.getOrDefault(dataFile.fileName(), Collections.emptyMap());
                files.add(new FilePlan(split, fileIndex, groups));
            }
        }
        return new Plan(snapshotId, files);
    }

public CompletableFuture<List<Result>> searchBatchAsync(
            PkVectorBucketIndexState state,
            List<DataFileMeta> activeFiles,
            Map<String, DeletionVector> deletionVectors,
            Map<String, List<Range>> rowRangesByFile,
            float[][] queries,
            int indexedLimit,
            int exactLimit,
            Executor executor) {
        checkArgument(queries != null && queries.length > 0, "Query vectors cannot be empty.");
        checkArgument(indexedLimit > 0, "Vector indexed search limit must be positive.");
        checkArgument(exactLimit > 0, "Vector exact search limit must be positive.");

        Map<String, DataFileMeta> filesByName = new HashMap<>();
        for (DataFileMeta file : activeFiles) {
            checkArgument(filesByName.put(file.fileName(), file) == null, "Duplicate data file.");
        }
        Set<String> activeSourceFiles = new HashSet<>(filesByName.keySet());
        Set<String> covered = new HashSet<>();
        List<CompletableFuture<List<List<PkVectorSearchResult>>>> indexedFutures =
                new ArrayList<>();
        for (IndexFileMeta ann : state.annSegments()) {
            PrimaryKeyIndexSourceMeta sourceMeta = PrimaryKeyIndexSourceMeta.fromIndexFile(ann);
            for (PrimaryKeyIndexSourceFile source : sourceMeta.sourceFiles()) {
                DataFileMeta file = filesByName.get(source.fileName());
                if (file == null) {
                    continue;
                }
                checkArgument(
                        file.rowCount() == source.rowCount(),
                        "ANN source %s does not match the active data file.",
                        source.fileName());
                covered.add(source.fileName());
            }
            checkArgument(annSearcher != null, "ANN search is not configured.");
            if (queries.length == 1) {
                indexedFutures.add(
                        annSearcher
                                .searchAsync(
                                        ann,
                                        sourceMeta,
                                        queries[0],
                                        indexedLimit,
                                        deletionVectors,
                                        activeSourceFiles,
                                        rowRangesByFile,
                                        searchOptions)
                                .thenApply(Collections::singletonList));
            } else {
                indexedFutures.add(
                        annSearcher.searchBatchAsync(
                                ann,
                                sourceMeta,
                                queries,
                                indexedLimit,
                                deletionVectors,
                                activeSourceFiles,
                                rowRangesByFile,
                                searchOptions));
            }
        }

        List<CompletableFuture<List<List<PkVectorSearchResult>>>> exactFutures = new ArrayList<>();
        if (searchMode != GlobalIndexSearchMode.FAST) {
            for (DataFileMeta file : activeFiles) {
                if (covered.contains(file.fileName())) {
                    continue;
                }
                DeletionVector dv = deletionVectors.get(file.fileName());
                List<Range> rowRanges = rowRangesByFile.get(file.fileName());
                if (rowRanges != null && rowRanges.isEmpty()) {
                    continue;
                }
                LongPredicate excluded =
                        position ->
                                (dv != null && dv.isDeleted(position))
                                        || (rowRanges != null && !contains(rowRanges, position));
                exactFutures.add(
                        CompletableFuture.supplyAsync(
                                () -> exactSearch(file, queries, exactLimit, excluded), executor));
            }
        }
        List<CompletableFuture<?>> futures = new ArrayList<>();
        futures.addAll(indexedFutures);
        futures.addAll(exactFutures);
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply(
                        ignored -> {
                            List<PriorityQueue<PkVectorSearchResult>> indexedNearest =
                                    queues(queries.length, indexedLimit);
                            for (CompletableFuture<List<List<PkVectorSearchResult>>> future :
                                    indexedFutures) {
                                List<List<PkVectorSearchResult>> batchResults = future.join();
                                checkArgument(
                                        batchResults.size() == queries.length,
                                        "ANN batch result count does not match query count.");
                                for (int i = 0; i < queries.length; i++) {
                                    for (PkVectorSearchResult result : batchResults.get(i)) {
                                        add(indexedNearest.get(i), result, indexedLimit);
                                    }
                                }
                            }
                            List<PriorityQueue<PkVectorSearchResult>> exactNearest =
                                    queues(queries.length, exactLimit);
                            for (CompletableFuture<List<List<PkVectorSearchResult>>> future :
                                    exactFutures) {
                                List<List<PkVectorSearchResult>> batchResults = future.join();
                                checkArgument(
                                        batchResults.size() == queries.length,
                                        "Exact batch result count does not match query count.");
                                for (int i = 0; i < queries.length; i++) {
                                    for (PkVectorSearchResult result : batchResults.get(i)) {
                                        add(exactNearest.get(i), result, exactLimit);
                                    }
                                }
                            }
                            List<Result> results = new ArrayList<>(queries.length);
                            for (int i = 0; i < queries.length; i++) {
                                results.add(
                                        new Result(
                                                sorted(indexedNearest.get(i)),
                                                sorted(exactNearest.get(i))));
                            }
                            return Collections.unmodifiableList(results);
                        });
    }

